const body = $json.body || $json;
const tag = String(body.tag || '').trim();
const slug = String(body.tournament_slug || body.slug || '').trim();
const attempt_id = body.attempt_id || String($execution.id);

if (!tag || !slug) {
  return [{ json: { ok: false, state: 'skipped', skipped: true, attempt_id,
    message: !tag ? 'Tag saknas' : 'Slug saknas' } }];
}

// User input is serialized as GraphQL variables, never interpolated into JSON/query text.
const query = 'query Q($slug: String!, $tag: String!) { tournament(slug: $slug) { id name participants(query: { filter: { gamerTag: $tag } }) { nodes { id gamerTag email user { name } events { id name } } } } }';
const requestBody = JSON.stringify({ query, variables: { slug, tag } });
return [{ json: { tag, slug, attempt_id, requestBody } }];

const ctx = $('Parse Input').first().json;
const attempt_id = ctx.attempt_id;
if (ctx.state === 'skipped') {
  return [{ json: { ok: false, state: 'skipped', skipped: true, attempt_id, message: ctx.message } }];
}
const response = $json;
const tournament = response.data?.tournament;
const participants = tournament?.participants?.nodes;
if (response.error || (Array.isArray(response.errors) && response.errors.length > 0) ||
    !tournament || !Array.isArray(participants)) {
  return [{ json: { ok: false, state: 'unavailable', error: 'api_unavailable', attempt_id,
    message: 'Start.gg kunde inte verifieras' } }];
}

// The API filter may return partial matches; require exact normalized equality locally.
const requestedTag = ctx.tag.trim().toLowerCase();
const player = participants.find(participant =>
  typeof participant?.gamerTag === 'string' &&
  participant.gamerTag.trim().toLowerCase() === requestedTag
);
if (!player) {
  return [{ json: { ok: true, state: 'verified_false', isRegistered: false,
    tournament: tournament.name, events: [], eventCount: 0, attempt_id, message: 'Ej registrerad' } }];
}
const events = (Array.isArray(player.events) ? player.events : [])
  .map(event => event?.name).filter(name => typeof name === 'string');
return [{ json: { ok: true, state: 'verified_true', isRegistered: true,
  tournament: tournament.name, tag: player.gamerTag, name: player.user?.name || null,
  events, eventCount: events.length, attempt_id } }];

